<?php
require_once __DIR__.'/../includes/auth.php';requireAdmin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$kind=$_POST['kind']??'';$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$level=$_POST['fitness_level']??'';$access=$_POST['access_type']??'';$guidance=trim((string)($_POST['guidance']??''));$extra=trim((string)($_POST['schedule_text']??''));if(!in_array($kind,['diet','workout'],true)||$title===''||!in_array($level,['beginner','intermediate','expert'],true)||!in_array($access,['free','premium'],true))$error='Complete all required fields with valid options.';else{if($kind==='diet'){$q=$pdo->prepare('INSERT INTO diet_plans(title,description,fitness_level,access_type,dietary_preference,guidance,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$title,$desc?:null,$level,$access,$_POST['dietary_preference']??'no_preference',$guidance?:null,$_SESSION['user_id']]);}else{$q=$pdo->prepare('INSERT INTO workout_templates(title,description,fitness_level,access_type,schedule_text,guidance,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$title,$desc?:null,$level,$access,$extra?:null,$guidance?:null,$_SESSION['user_id']]);}flash('Plan published.');redirect('plans.php');}}
$diets=$pdo->query('SELECT * FROM diet_plans ORDER BY created_at DESC')->fetchAll();$workouts=$pdo->query('SELECT * FROM workout_templates ORDER BY created_at DESC')->fetchAll();$pageTitle='Plan management';require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">CONTENT MANAGEMENT</p><h1>Diet & workout plans</h1><p>Create content matched to fitness level and free/premium access.</p></div></section><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Create a plan</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><div><label>Plan type</label><select name="kind"><option value="diet">Diet guidance</option><option value="workout">Workout plan</option></select></div><div><label>Title</label><input name="title" required maxlength="160"></div><div><label>Fitness level</label><select name="fitness_level"><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="expert">Expert</option></select></div><div><label>Access</label><select name="access_type"><option value="free">Free</option><option value="premium">Premium</option></select></div><div><label>Diet preference (diet plans)</label><select name="dietary_preference"><option value="no_preference">Any preference</option><option value="vegetarian">Vegetarian</option><option value="vegan">Vegan</option><option value="pescatarian">Pescatarian</option><option value="other">Other</option></select></div><div class="full"><label>Description</label><textarea name="description" rows="2"></textarea></div><div class="full"><label>Schedule text (workout plans)</label><textarea name="schedule_text" rows="2"></textarea></div><div class="full"><label>Guidance / details</label><textarea name="guidance" rows="4"></textarea></div><div><button class="button">Publish plan</button></div></form></section><div class="cols"><section class="panel"><h2>Diet plans (<?=count($diets)?>)</h2><?php foreach($diets as $p):?><article class="notification-row"><div><strong><?=e($p['title'])?></strong><p><?=e(ucfirst($p['fitness_level']))?> · <?=e(ucfirst($p['access_type']))?></p></div></article><?php endforeach;?></section><section class="panel"><h2>Workout plans (<?=count($workouts)?>)</h2><?php foreach($workouts as $p):?><article class="notification-row"><div><strong><?=e($p['title'])?></strong><p><?=e(ucfirst($p['fitness_level']))?> · <?=e(ucfirst($p['access_type']))?></p></div></article><?php endforeach;?></section></div><?php require __DIR__.'/../includes/footer.php';?>
